/**
 * test subclass of DistCp can invoke cleanup() to remove the staging
 * folder after a copy.
 * @throws Exception
 */
@Test
public void testCleanupViaSubClass() throws Exception {

  Configuration conf = getConf();

  Path stagingDir = JobSubmissionFiles.getStagingDir(new Cluster(conf),
      conf);
  stagingDir.getFileSystem(conf).mkdirs(stagingDir);
  Path soure = createFile("tmp.txt");
  Path target = createFile("target.txt");

  DistCpSubClass distcp = new DistCpSubClass(conf, null);
  String[] arg = { soure.toString(), target.toString() };

  distcp.run(arg);
  Assert.assertTrue(fs.exists(target));
  Assert.assertNull("Meta folder should be null after cleanup",
      distcp.getMetaFolder());
  Assert.assertEquals("Staging folder should be empty after cleanup", 0,
      stagingDir.getFileSystem(conf).listStatus(stagingDir).length);
}

private static class DistCpSubClass extends DistCp {

  DistCpSubClass(Configuration conf, DistCpOptions inputOptions)
      throws Exception {
    super(conf, inputOptions);
  }

  @Override
  protected synchronized void cleanup() {
    super.cleanup();
  }

  Path getMetaFolder() throws Exception {
    java.lang.reflect.Field metaFolder =
        DistCp.class.getDeclaredField("metaFolder");
    metaFolder.setAccessible(true);
    return (Path) metaFolder.get(this);
  }
}

