1139	  public void testCreateJarWithClassPath() throws Exception {
1140	    // create files expected to match a wildcard
1141	    List<File> wildcardMatches = Arrays.asList(new File(tmp, "wildcard1.jar"),
1142	      new File(tmp, "wildcard2.jar"), new File(tmp, "wildcard3.JAR"),
1143	      new File(tmp, "wildcard4.JAR"));
1144	    for (File wildcardMatch: wildcardMatches) {
1145	      Assert.assertTrue("failure creating file: " + wildcardMatch,
1146	        wildcardMatch.createNewFile());
1147	    }
1148	
1149	    // create non-jar files, which we expect to not be included in the classpath
1150	    Assert.assertTrue(new File(tmp, "text.txt").createNewFile());
1151	    Assert.assertTrue(new File(tmp, "executable.exe").createNewFile());
1152	    Assert.assertTrue(new File(tmp, "README").createNewFile());
1153	
1154	    // create classpath jar
1155	    String wildcardPath = tmp.getCanonicalPath() + File.separator + "*";
1156	    String nonExistentSubdir = tmp.getCanonicalPath() + Path.SEPARATOR + "subdir"
1157	      + Path.SEPARATOR;
1158	    List<String> classPaths = Arrays.asList("", "cp1.jar", "cp2.jar", wildcardPath,
1159	      "cp3.jar", nonExistentSubdir);
1160	    String inputClassPath = StringUtils.join(File.pathSeparator, classPaths);
1161	    String[] jarCp = FileUtil.createJarWithClassPath(inputClassPath + File.pathSeparator + "unexpandedwildcard/*",
1162	      new Path(tmp.getCanonicalPath()), System.getenv());
1163	    String classPathJar = jarCp[0];
1164	    assertNotEquals("Unexpanded wildcard was not placed in extra classpath", jarCp[1].indexOf("unexpanded"), -1);
1165	
1166	    // verify classpath by reading manifest from jar file
1167	    JarFile jarFile = null;
1168	    try {
1169	      jarFile = new JarFile(classPathJar);
1170	      Manifest jarManifest = jarFile.getManifest();
1171	      Assert.assertNotNull(jarManifest);
1172	      Attributes mainAttributes = jarManifest.getMainAttributes();
1173	      Assert.assertNotNull(mainAttributes);
1174	      Assert.assertTrue(mainAttributes.containsKey(Attributes.Name.CLASS_PATH));
1175	      String classPathAttr = mainAttributes.getValue(Attributes.Name.CLASS_PATH);
1176	      Assert.assertNotNull(classPathAttr);
1177	      List<String> expectedClassPaths = new ArrayList<String>();
1178	      for (String classPath: classPaths) {
1179	        if (classPath.length() == 0) {
1180	          continue;
1181	        }
1182	        if (wildcardPath.equals(classPath)) {
1183	          // add wildcard matches
1184	          for (File wildcardMatch: wildcardMatches) {
1185	            expectedClassPaths.add(wildcardMatch.toURI().toURL()
1186	              .toExternalForm());
1187	          }
1188	        } else {
1189	          File fileCp = null;
1190	          if(!new Path(classPath).isAbsolute()) {
1191	            fileCp = new File(tmp, classPath);
1192	          }
1193	          else {
1194	            fileCp = new File(classPath);
1195	          }
1196	          if (nonExistentSubdir.equals(classPath)) {
1197	            // expect to maintain trailing path separator if present in input, even
1198	            // if directory doesn't exist yet
1199	            expectedClassPaths.add(fileCp.toURI().toURL()
1200	              .toExternalForm() + Path.SEPARATOR);
1201	          } else {
1202	            expectedClassPaths.add(fileCp.toURI().toURL()
1203	              .toExternalForm());
1204	          }
1205	        }
1206	      }
1207	      List<String> actualClassPaths = Arrays.asList(classPathAttr.split(" "));
1208	      Collections.sort(expectedClassPaths);
1209	      Collections.sort(actualClassPaths);
1210	      Assert.assertEquals(expectedClassPaths, actualClassPaths);
1211	    } finally {
1212	      if (jarFile != null) {
1213	        try {
1214	          jarFile.close();
1215	        } catch (IOException e) {
1216	          LOG.warn("exception closing jarFile: " + classPathJar, e);
1217	        }
1218	      }
1219	    }
1220	  }
