1375	  private void putEntriesInTar(TarArchiveOutputStream tos, File f)
1376	      throws IOException {
1377	    if (Files.isSymbolicLink(f.toPath())) {
1378	      TarArchiveEntry tarEntry = new TarArchiveEntry(f.getPath(),
1379	          TarArchiveEntry.LF_SYMLINK);
